import {themes,filterCases,countsBy,sortCases,csv,timelineLayout,timelineBounds} from './engine.mjs';
import './guide.mjs';
const $=s=>document.querySelector(s), escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=d=>new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(d+'T00:00:00Z'));
const state={category:''};let data,all=[],opener;
const cardPageSize=6;let cardLimit=cardPageSize,cardSelectionKey='';
const outcomes={'Reported controversy':'#577f86','Official finding':'#356c61','Court decision':'#496fa1','Guilty plea / sentencing':'#254d60','Settlement / final order':'#839a6d','Settlement announced':'#b18b48','Reported investigation':'#c47856','Investigation closed':'#a2b8aa','Order set aside':'#80619c','Mixed proceedings':'#746486','Company acknowledgement':'#657e8c','Policy reversed':'#a18b63','No discrimination found':'#5b8875','Research finding':'#8c7665','Reported account':'#b07854','Official finding / appeal pending':'#8b6d99','Corrective recommendations':'#6b8f8d'};
const storySteps=[
 {symbol:'@',title:'A message from the “CFO”.',text:'A phishing email impersonated the company’s chief financial officer.',label:'01 / THE APPROACH'},
 {symbol:'▣',title:'A familiar face on a screen.',text:'Police described a pre-recorded deepfake meeting, with no interaction.',label:'02 / THE MEETING'},
 {symbol:'↗',title:'The instructions moved to chat.',text:'After the meeting, payment instructions continued through instant messaging.',label:'03 / THE TRANSFER'},
 {symbol:'HK$',title:'About HK$200 million lost.',text:'The government reported this loss. The case was under investigation in June 2024.',label:'04 / THE REPORTED OUTCOME'}
];let storyIndex=0;
function renderStory(){const s=storySteps[storyIndex];$('#story-progress').textContent=`0${storyIndex+1} / 04`;$('#story-scene').innerHTML=`<div class="scene-symbol" aria-hidden="true">${s.symbol}</div><p class="eyebrow">${s.label}</p><h3>${s.title}</h3><p>${s.text}</p>`;$('#story-tabs').innerHTML=storySteps.map((s,i)=>`<button data-step="${i}" aria-label="Step ${i+1}: ${escape(s.title)}" aria-pressed="${i===storyIndex}" class="${i===storyIndex?'selected':''}">${i+1}</button>`).join('');$('#story-prev').disabled=storyIndex===0;$('#story-next').disabled=storyIndex===3}
$('#story-prev').onclick=()=>{if(storyIndex>0)storyIndex--;renderStory()};$('#story-next').onclick=()=>{if(storyIndex<3)storyIndex++;renderStory()};renderStory();
const notify=message=>{const el=$('#notification');el.textContent=message;el.hidden=false;setTimeout(()=>el.hidden=true,3500)};
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function render(){
 const f={...state,search:$('#search').value,region:$('#region').value,year:$('#year').value,status:$('#status').value};const selected=filterCases(all,f);const counts=countsBy(selected,'category');
 const selectionKey=JSON.stringify([f,$('#sort').value]);if(selectionKey!==cardSelectionKey){cardLimit=cardPageSize;cardSelectionKey=selectionKey}
 $('#visible-count').textContent=`${selected.length} of ${all.length} records`;
 const statusCounts=countsBy(selected,'status');$('#outcome-strip').innerHTML=Object.entries(outcomes).filter(([s])=>statusCounts[s]).map(([s,color])=>`<span style="flex:${statusCounts[s]};background:${color}" title="${escape(s)}: ${statusCounts[s]}"></span>`).join('');$('#outcome-legend').innerHTML=Object.entries(outcomes).filter(([s])=>statusCounts[s]).map(([s,color])=>`<button data-status="${escape(s)}" aria-label="Show ${escape(s)}" style="--color:${color}"><span class="chip-dot"></span>${escape(s)} <b>${statusCounts[s]}</b></button>`).join('')||'<span>No outcomes in this selection</span>';
 $('#chips').innerHTML=[['','All themes'],...Object.keys(themes).map(x=>[x,x])].map(([key,label])=>`<button class="chip ${key===state.category?'active':''}" data-theme="${escape(key)}" aria-pressed="${key===state.category}" style="--color:${themes[key]||'#a5b4a7'}"><span class="chip-dot"></span>${escape(label)}</button>`).join('');
 const bounds=timelineBounds(all),{start,end,years}=bounds;
 $('#timeline').innerHTML=`<div class="timeline-axis"><span class="row-label">Publication year</span><div class="years">${years.filter((y,i)=>innerWidth>=650||i%2===0).map(y=>`<span style="left:${100*(Date.UTC(y,0,1)-start)/(end-start)}%">${y}</span>`).join('')}</div></div>`+Object.entries(themes).map(([theme,color])=>{const group=selected.filter(c=>c.category===theme);const layout=timelineLayout(group,innerWidth<650?8:4,bounds);const height=Math.max(43,Math.max(0,...layout.map(p=>p.lane))*20+28);return `<div class="timeline-row"><span class="row-label">${escape(theme)}</span><div class="track" style="height:${height}px;background-size:${100/years.length}% 100%">${layout.map(p=>{const c=group.find(c=>c.id===p.id);return `<button class="point" data-case="${c.id}" style="--pos:${p.pos}%;--top:${14+p.lane*20}px;--color:${color}" aria-label="${escape(c.entity)}, ${date(c.recordDate)}, ${escape(c.status)}" title="${escape(c.entity)} · ${date(c.recordDate)}"></button>`}).join('')}</div></div>`}).join('');
 $('#bars').innerHTML=Object.entries(themes).map(([theme,color])=>`<button class="bar-button" data-theme="${escape(theme)}" aria-label="Filter ${escape(theme)}: ${counts[theme]||0} records"><span class="bar-label"><span>${escape(theme)}</span><b>${counts[theme]||0}</b></span><div class="bar-track"><div class="bar-fill" style="--color:${color};--width:${selected.length?100*(counts[theme]||0)/selected.length:0}%"></div></div></button>`).join('');
 $('#cards').innerHTML=sortCases(selected,$('#sort').value).slice(0,cardLimit).map(c=>`<button class="case-card" data-case="${c.id}" style="--color:${themes[c.category]}" aria-label="Read case: ${escape(c.entity)}"><span class="card-meta"><span class="category-tag">${escape(c.category)}</span><span>${c.recordDate.slice(0,4)}</span></span><h4>${escape(c.title)}</h4><span class="card-entity">${escape(c.entity)} · ${escape(c.jurisdiction)}</span><p class="card-summary">${escape(c.summary)}</p><span class="card-bottom"><span><span class="status-tag ${c.status==='Order set aside'?'changed':''}">${escape(c.status)}</span><small class="outcome-date">Outcome as of ${date(c.outcomeAsOf)}</small></span><b aria-hidden="true">↗</b></span></button>`).join('');$('#empty').hidden=selected.length>0;
 $('#cards-footer').hidden=selected.length===0;$('#cards-count').textContent=`Showing ${Math.min(cardLimit,selected.length)} of ${selected.length} matching cases`;$('#show-more').hidden=cardLimit>=selected.length;
}
$('#show-more').onclick=()=>{const firstNewIndex=cardLimit;cardLimit+=cardPageSize;render();$('#cards').children[firstNewIndex]?.focus({preventScroll:true})};
function openCase(id,updateHash=true){const c=all.find(x=>x.id===id);if(!c)return;opener=document.activeElement;const block=(title,body,cls='')=>`<section class="detail-block ${cls}"><h3>${title}</h3><p>${escape(body)}</p></section>`;
 $('#case-content').innerHTML=`<p class="detail-eyebrow" style="--color:${themes[c.category]}">${escape(c.category)} / ${escape(c.entity)}</p><h2 id="case-title">${escape(c.title)}</h2><p class="detail-summary">${escape(c.summary)}</p><dl class="fact-grid">${[['Event period',c.eventPeriod],['Public record date',date(c.recordDate)],['Jurisdiction',c.jurisdiction],['Technology / claim',c.technology],['Outcome in cited source',c.status],['Outcome as of',date(c.outcomeAsOf)]].map(([k,v])=>`<div><dt>${k}</dt><dd>${escape(v)}</dd></div>`).join('')}</dl>${block('How AI or automation was involved',c.aiRole)}${block('Who was affected',c.affected)}${block('What the cited record says happened next',c.outcome)}${block('What this does not establish',c.limitation,'caution')}${block('A lesson to take away',c.lesson,'lesson')}<details class="detail-block review-notes"><summary>Source review notes (AI-assisted)</summary><p><strong>Evidence basis:</strong> ${escape(c.review.basis)}</p><p><strong>Account locator:</strong> ${escape(c.review.supportLocators.summaryAndAiRole)}</p><p><strong>Outcome locator:</strong> ${escape(c.review.supportLocators.outcome)}</p><p><strong>Number and scope checks:</strong> ${escape(c.review.numberAndScopeChecks)}</p><p><strong>Coverage:</strong> ${escape(c.review.statusCoverage)}</p></details><section class="detail-block"><h3>Follow the sources</h3><ul class="sources-list">${c.sources.map(s=>`<li><a href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">${escape(s.label)} ↗</a><small>${escape(s.publisher)} · ${date(s.date)} · ${escape(s.type)}</small>${s.reuseNote?`<small>${escape(s.reuseNote)}${s.reuseLicenceUrl?` <a href="${escape(s.reuseLicenceUrl)}" target="_blank" rel="noopener noreferrer">Licence ↗</a>`:''}</small>`:''}</li>`).join('')}</ul><p>Source review: ${date(c.review.checkedOn)}. Outcomes are dated to the cited documents and may have changed later. Research and summaries were prepared with AI assistance; these checks are not independent expert verification. Lessons and themes are editorial interpretation.</p></section><div class="detail-actions"><button id="copy-link">Copy case link</button><span>Keep the context with the story.</span></div>`;
 if(!$('#case-dialog').open)$('#case-dialog').showModal();$('#close-dialog').focus();if(updateHash)history.replaceState(null,'',`#case/${id}`);
 $('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);notify('Case link copied')}catch{notify('Copy the case URL from your address bar')}};
}
document.addEventListener('click',e=>{const step=e.target.closest('[data-step]');if(step){storyIndex=Number(step.dataset.step);renderStory()}const status=e.target.closest('[data-status]');if(status){$('#status').value=status.dataset.status;render()}const caseButton=e.target.closest('[data-case]');if(caseButton)openCase(caseButton.dataset.case);const themeButton=e.target.closest('[data-theme]');if(themeButton){state.category=themeButton.dataset.theme;render()}});
$('#filters').onsubmit=e=>e.preventDefault();$('#filters').addEventListener('input',()=>data&&render());$('#filters').addEventListener('change',()=>data&&render());$('#filters').addEventListener('reset',()=>{state.category='';setTimeout(()=>data&&render(),0)});$('#sort').onchange=()=>data&&render();
$('#close-dialog').onclick=()=>$('#case-dialog').close();$('#case-dialog').addEventListener('click',e=>{if(e.target===$('#case-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});$('#case-dialog').addEventListener('close',()=>{if(location.hash.startsWith('#case/'))history.replaceState(null,'','#explore');if(opener?.isConnected)opener.focus()});window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#case/'))openCase(location.hash.slice(6),false)});
$('#export').onclick=()=>{if(!data)return;download('ai-headlines-reviewed-cases.csv',csv(all),'text/csv;charset=utf-8');notify(`Downloaded all ${all.length} records, including sources and limitations`)};
try{const response=await fetch('data/cases.json');if(!response.ok)throw Error('Dataset unavailable');data=await response.json();all=data.cases;$('#total').textContent=all.length;$('#themes').textContent=Object.keys(countsBy(all,'category')).length;$('#regions').textContent=Object.keys(countsBy(all,'jurisdiction')).length;$('#review-date').textContent=date(data.reviewedOn);for(const [id,field]of [['region','jurisdiction'],['year','recordDate'],['status','status']]){const values=[...new Set(all.map(c=>field==='recordDate'?c[field].slice(0,4):c[field]))].sort();for(const value of values){const option=document.createElement('option');option.value=value;option.textContent=value;$('#'+id).append(option)}}render();if(location.hash.startsWith('#case/'))openCase(location.hash.slice(6),false)}catch(e){$('#visible-count').textContent='Could not load data';$('#empty').hidden=false;$('#empty').textContent='The collection could not load. Please reload, or download the dataset below.';console.error(e)}
